 . "$PSScriptRoot/../src/Validation.ps1"; $r=Invoke-TrackingImportExtended -LabelString "PN=12345678;SN=ABC123;HW=04;SW=12" -QRString "PN=12345678;SN=ABC123;HW=04;SW=13" -Derivat "G20" -IStufe "26-07" -DryRun; if($r.ValidationStatus -ne "LABEL_QR_MISMATCH"){ throw "Test fehlgeschlagen: erwartet LABEL_QR_MISMATCH, erhalten $($r.ValidationStatus)" }; Write-Host "TEST OK: Label/QR-Abweichung erkannt"
$ok=Test-LabelQrMatchExtended -LabelPartNumber "123" -QRPartNumber "123" -LabelSerialNumber "ABC" -QRSerialNumber "ABC" -LabelHardware "01" -QRHardware "01" -LabelSoftware "02" -QRSoftware "02"; if($ok -ne "OK"){throw "OK-Test fehlgeschlagen"}; $dd=Get-DuplicateStatus -ExistingDeviceKey "123|ABC" -ExistingAssignmentKey "123|ABC|G20|26-07" -NewDeviceKey "123|ABC" -NewAssignmentKey "123|ABC|G21|26-07"; if($dd -ne "DOUBLE_DERIVATIVE"){throw "DOUBLE_DERIVATIVE-Test fehlgeschlagen"}; $dup=Get-DuplicateStatus -ExistingDeviceKey "123|ABC" -ExistingAssignmentKey "123|ABC|G20|26-07" -NewDeviceKey "123|ABC" -NewAssignmentKey "123|ABC|G20|26-07"; if($dup -ne "DUPLICATE"){throw "DUPLICATE-Test fehlgeschlagen"}; Write-Host "TEST OK: OK, Doppelderivat und Duplikat erkannt"
$DuplicateStatus="DOUBLE_DERIVATIVE"; $FinalStatus="LABEL_QR_MISMATCH"; $dd=($DuplicateStatus -eq "DOUBLE_DERIVATIVE"); if(($FinalStatus -ne "LABEL_QR_MISMATCH") -or (-not $dd)){throw "Kombinationstest fehlgeschlagen"}; Write-Host "TEST OK: Label/QR-Abweichung und Doppelderivat gleichzeitig erkannt"
